        if self.0.fetch_add(1, Ordering::SeqCst) == 0 {
            return Err(TimeSampleError::new("injected network outage"));
        }
        Ok(TimeSample {
            source: "recovered-sntp".to_owned(),
            unix_millis: 1_720_000_000_000,
            offset_millis: 0,
            round_trip: Duration::from_millis(1),
        })
    }
}

