                .ok_or_else(|| ComponentError::new("declared input closed"))?;
            self.observed.store(value.sequence, Ordering::SeqCst);
            assert!(context.recv::<TestEvent>("undeclared").await.is_err());
            context.ready();
            context.cancellation.cancelled().await;
        }
        Ok(())
    }
}

