async fn spawn_mtls_peer_with_fixture(
    secret: ProtocolSecret,
    responses: Vec<ProtocolStatus>,
    fixture: MtlsFixture,
) -> (
    std::net::SocketAddr,
    ProtocolSecurity,
    String,
    Arc<Mutex<Option<String>>>,
) {
