#[derive(Debug, Clone, Deserialize, PartialEq, Eq)]
struct TestConfig {
    name: String,
    workers: u32,
    left: u32,
    right: u32,
}

fn parser() -> ConfigParser<TestConfig> {
    Arc::new(|raw| {
        let config: TestConfig =
            toml::from_str(raw).map_err(|error| ConfigReloadError::parse(error.to_string()))?;
        if config.name.trim().is_empty() {
            return Err(ConfigReloadError::validation("name is required"));
        }
        if config.workers == 0 {
            return Err(ConfigReloadError::validation("workers must be positive"));
        }
        if config.left != config.right {
            return Err(ConfigReloadError::validation("pair must be complete"));
        }
        Ok(config)
    })
}

fn options() -> ConfigReloadOptions {
    ConfigReloadOptions {
        poll_interval: Duration::from_millis(10),
        debounce: Duration::from_millis(40),
    }
}

fn render(name: &str, workers: u32, pair: u32) -> String {
    format!("name = \"{name}\"\nworkers = {workers}\nleft = {pair}\nright = {pair}\n")
}

async fn write_config(path: &std::path::Path, body: String) {
    // Publish one complete candidate so the watcher cannot observe a truncated file.
    let staged = path.with_extension("toml.next");
    tokio::fs::write(&staged, body).await.expect("stage config");
    tokio::fs::rename(&staged, path)
        .await
        .expect("publish config");
}

async fn wait_for_generation(
    handle: &HotReloadHandle<TestConfig>,
    generation: u64,
) -> Arc<adl_runtime::config_reload::ConfigSnapshot<TestConfig>> {
    let mut watcher = handle.clone();
    timeout(Duration::from_secs(2), async {
        loop {
            let snapshot = handle.current();
            if snapshot.generation() >= generation {
                return snapshot;
            }
            let snapshot = watcher.changed().await.expect("watcher update");
            if snapshot.generation() >= generation {
                return snapshot;
            }
        }
    })
    .await
    .expect("generation observed")
}

async fn wait_for_reload_status(
    handle: &HotReloadHandle<TestConfig>,
    predicate: impl Fn(adl_runtime::config_reload::ConfigReloadStatus) -> bool,
) -> adl_runtime::config_reload::ConfigReloadStatus {
    let mut watcher = handle.clone();
    timeout(Duration::from_secs(2), async {
        loop {
            let status = watcher.reload_status();
            if predicate(status) {
                return status;
            }
            let status = watcher
                .reload_status_changed()
                .await
                .expect("reload status update");
            if predicate(status) {
                return status;
            }
        }
    })
    .await
    .expect("reload status observed")
}

