    fn current_observer_identity(&self, node: &str) -> Option<(u64, VerifyingKey)> {
        self.keys
            .get(&(node.to_owned(), 1))
            .copied()
            .map(|key| (1, key))
    }

    fn is_member(&self, node: &str, epoch: u64) -> bool {
        self.members.contains(&(node.to_owned(), epoch))
    }
