        .unwrap()
        .join("certificates.redb");
    let store = DistributedCertificateStore::open(
        &TEST_CERTIFICATE_STORE_ACCESS,
        database,
        certificate_policy,
    )
    .unwrap();
    let _ = directory.keep();
    (Arc::new(store), root)
}

fn transport_authorization(
    store: &Arc<DistributedCertificateStore>,
