/// PVF #213: required installed-intent lane on native Linux CI and local macOS.
/// Seven registered worktrees and 23,000 reachable packed objects exercise the
/// full installed process; synthetic transport avoids live network dependence.
fn issue213_seed_realistic_git_scale(root: &Path) {
    use std::fmt::Write as _;
    use std::io::Write as _;
    use std::process::Stdio;

    let mut stream = String::with_capacity(2_000_000);
    stream.push_str("commit refs/heads/scale-objects\n");
    stream.push_str("committer Fixture <fixture@example.invalid> 0 +0000\n");
    stream.push_str("data 5\nscale\n");
    for index in 0..23_000 {
        let blob = format!("scale-{index:05}\n");
        write!(
            stream,
            "M 100644 inline objects/{index:05}.txt\ndata {}\n{blob}",
            blob.len()
        )
        .unwrap();
    }
    stream.push('\n');
    let mut import = Command::new("git")
        .args(["fast-import", "--quiet"])
        .current_dir(root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    import
        .stdin
        .take()
        .unwrap()
        .write_all(stream.as_bytes())
        .unwrap();
    let output = import.wait_with_output().unwrap();
    assert!(output.status.success(), "git fast-import: {output:?}");
    git(root, &["gc", "--quiet"]);

    for index in 1..=6 {
        let target = root.join(format!("worktrees/scale-{index}"));
        git(
            root,
            &[
                "worktree",
                "add",
                "--quiet",
                "--detach",
                target.to_str().unwrap(),
                "HEAD",
            ],
        );
    }
    let worktrees = git(root, &["worktree", "list", "--porcelain"])
        .lines()
        .filter(|line| line.starts_with("worktree "))
        .count();
    let packed = git(root, &["count-objects", "-v"])
        .lines()
        .find_map(|line| line.strip_prefix("in-pack: "))
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap();
    assert_eq!(worktrees, 7);
    assert!(
        packed >= 23_000,
        "expected >=23,000 packed objects, got {packed}"
    );
}

