        .chain(csdlc_v3::application::intent::INTENTS.iter())
        .map(|s| (*s).into())
        .collect();
    expected.extend(
        [
            "foundation",
            "local",
            "remote",
            "sprint",
            "release-preflight",
            "rollback",
            "github-issue create",
