#[test]
// PVF: deterministic read-only real-record canary; small CPU/disk; required tooling proof.
// Explicit topology outcomes preserve the primary legacy-state recovery boundary.
fn eligibility_cli_consumes_real_bound_issue_state() {
    let root = repo_root();
    let registry = prompt_registry(&root);
    let request = real_issue_request(&root, 5853, &registry);
    let dir = root.join("csdlc-v3/target/real-issue-canary-5853");
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("real issue canary fixture dir");
    let request_path = dir.join("request.json");
    let registrations_path = dir.join("registrations.json");
    fs::write(
        &request_path,
        serde_json::to_vec(&request).expect("real request serializes"),
    )
    .expect("write real request fixture");
    fs::write(
        &registrations_path,
        serde_json::to_vec(&[WorktreeRegistration {
            branch: request.branch.clone(),
            worktree: request.worktree.clone(),
            primary: false,
        }])
        .expect("real registration serializes"),
    )
    .expect("write real registration fixture");

    let primary = primary_repo_root(&root);
    let discovery =
        csdlc_v3::commands::local::discover_operational_local_context(&primary, &request);
    let expected_denial = match &discovery {
        Ok(Some(_)) if primary.join(".csdlc/issues/5853").exists() => {
            Some("legacy_primary_state_requires_recovery")
        }
        Ok(_) => None,
        Err(findings) => {
            assert!(
                findings
                    .iter()
                    .all(|f| f.code == "worktree_parent_unavailable"),
                "{findings:?}"
            );
            Some("worktree_parent_unavailable")
        }
    };
    fn snapshot(path: &Path, entries: &mut BTreeMap<PathBuf, Vec<u8>>) {
        match fs::symlink_metadata(path) {
            Ok(metadata) if metadata.is_dir() => {
                entries.insert(path.to_path_buf(), Vec::new());
                for entry in fs::read_dir(path).unwrap() {
                    snapshot(&entry.unwrap().path(), entries);
                }
            }
            Ok(metadata) => {
                assert!(
                    metadata.is_file(),
                    "unexpected nonregular fixture state: {path:?}"
                );
                entries.insert(path.to_path_buf(), fs::read(path).unwrap());
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => panic!("snapshot {path:?}: {error}"),
        }
    }
    let state_root = csdlc_v3::commands::local::operational_state_root(&primary).unwrap();
    let watched = [
        primary.join(".csdlc/issues/5853"),
        primary.join(".csdlc/prepared/issues/5853"),
        primary.join(".csdlc/transactions/5853.json"),
        primary.join(".csdlc/transactions/completed/5853"),
        state_root.join("issues/5853"),
        state_root.join("transactions/5853.json"),
        state_root.join("transactions/completed/5853"),
        state_root.join("bindings/5853.json"),
        state_root.join("locks/5853.lock"),
    ];
    let mut before = BTreeMap::new();
    for path in &watched {
        snapshot(path, &mut before);
    }

    let output = Command::new(env!("CARGO_BIN_EXE_csdlc"))
        .arg("eligibility")
        .arg("--request")
        .arg(&request_path)
        .arg("--registry")
        .arg(root.join("docs/templates/prompts/current.json"))
        .arg("--registrations")
        .arg(&registrations_path)
        .arg("--repo-root")
        .arg(&primary)
        .output()
        .expect("run eligibility canary against real bound issue");
    let mut after = BTreeMap::new();
    for path in &watched {
        snapshot(path, &mut after);
    }
    assert_eq!(
        after, before,
        "read-only eligibility must preserve issue state"
    );
    if let Some(expected_code) = expected_denial {
        assert_eq!(output.status.code(), Some(2), "{output:?}");
        let value: serde_json::Value = serde_json::from_slice(&output.stdout)
            .expect("blocked eligibility emits machine JSON on stdout");
        assert_eq!(value["schema"], "csdlc.v3.operational_diagnostic.v1");
        assert_eq!(value["command"], "eligibility");
        assert_eq!(value["status"], "blocked");
        assert_eq!(value["read_only"], true);
        assert_eq!(value["writes_v3_state"], false);
        assert_eq!(
            std::str::from_utf8(&output.stderr).unwrap(),
            format!("csdlc: {expected_code}; see structured stdout findings\n")
        );
        let findings = value["findings"].as_array().expect("finding array");
        assert_eq!(findings.len(), 1, "{findings:?}");
        assert_eq!(findings[0]["code"], expected_code);
        assert_eq!(findings[0]["status"], "blocked");
        return;
    }
    assert!(output.status.success(), "{output:?}");
    assert!(output.stderr.is_empty(), "{output:?}");
    let value: serde_json::Value =
        serde_json::from_slice(&output.stdout).expect("eligibility emits machine JSON");
    assert_eq!(value["schema"], "csdlc.v3.operational_local.v1");
    assert_eq!(value["command"], "eligibility");
    assert_eq!(value["operational_authority"], true);
    assert_eq!(value["read_only"], true);
    assert_eq!(value["writes_v3_state"], false);
    let route_result = &value["result"];
    assert_eq!(route_result["route"], "eligibility");
    assert_eq!(route_result["mutated"], false);
    assert_eq!(route_result["issue"], 5853);
    let lifecycle_state = route_result;
    assert_eq!(lifecycle_state["phase"], "bound");
    assert!(lifecycle_state["findings"]
        .as_array()
        .expect("eligibility findings")
        .iter()
        .any(|finding| finding["code"] == "binding_live" && finding["status"] == "passed"));
}

