        selected_binary_provenance: format!("git:{revision}"),
        rollback_evidence: ".csdlc/evidence/505/v3-proof/rollback-readiness.json".into(),
        undo_boundary: "fail-closed before irreversible mutation".into(),
        operation,
        execute: true,
