    let bytes = serde_json::to_vec(&receipt).unwrap();
    fs::write(root.join(&path), &bytes).unwrap();

    serde_json::json!({
        "path": path,
        "digest": blake3::hash(&bytes).to_hex().to_string(),
        "revision": revision
    })
